SELECT /*LGUTLC00220.retrieveBatchScheduleList*/ lbm.batch_id, lbm.system_code, lbm.module_code, lbm.program_id, lpm.program_name, lbm.batch_name, argument_text, to_char( request_start_date, 'yyyy-mm-dd hh24:mi:ss' ) as request_start_date, to_char( request_end_date, 'yyyy-mm-dd hh24:mi:ss' ) as request_end_date, submit_interval, submit_interval_unit_code, submit_interval_type_code, lbm.run_alone_flag, lbm.use_flag, lbm.hold_flag, lbm.created_by as requester_id, lum.full_name_local as requester_name, lum.full_name_local ||'/'||lum.title_name||'/'|| lum.organization_name_eng as requester_full_name FROM lgcom_batch_m lbm, lgcom_user_m_v lum, lgcom_program_m lpm WHERE nvl(lbm.request_end_date, to_date('9999-12-31', 'yyyy-mm-dd')) > sysdate and lbm.created_by = lum.application_user_id and lbm.program_id = lpm.program_id
and lbm.system_code = #{systemCode}
and lbm.module_code = #{moduleCode}
and lbm.created_by = #{employeeIds}
and lbm.batch_name like '%'||#{batchName}||'%'
and lbm.hold_flag = #{holdFlag}
